select '9e27dc16-a3e0-5383-baea-91e63ba0ccec', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.BIO'), 'qa_passed', 'discontinuous', '{"title":"Estudio de un río","text":"Un grupo ambiental tomó muestras de agua en tres puntos de un río: antes de un pueblo (punto A), justo después de la descarga de aguas residuales del pueblo (punto B) y 5 km más abajo (punto C).","svg":null,"table":{"caption":"Resultados de las muestras","headers":["Punto","Oxígeno disuelto (mg/L)","Bacterias coliformes (por 100 mL)"],"rows":[["A",8.5,120],["B",3.2,25000],["C",6.1,2400]]}}'::jsonb, 'Para afirmar que las aguas residuales causan los cambios, ¿qué dato adicional sería más útil?', '[{"label":"A","text":"Mediciones repetidas en varios días en los tres puntos.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Permitirían descartar que sea un resultado de un solo día."},{"label":"B","text":"Una sola muestra más en el punto A.","is_correct":false,"distractor_type":"Da una evidencia insuficiente.","explanation_feedback":"Incorrecta. Una muestra más en A no confirma la causa."},{"label":"C","text":"El color de las piedras del río.","is_correct":false,"distractor_type":"Da un dato irrelevante.","explanation_feedback":"Incorrecta. No se relaciona con la contaminación medida."},{"label":"D","text":"El número de habitantes del país.","is_correct":false,"distractor_type":"Da un dato muy general.","explanation_feedback":"Incorrecta. No se relaciona con este río."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
