select '8b97f67c-222a-5962-8c72-2a5a4ef79dda', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Bicarbonato y vinagre","text":"En un experimento se mezclan bicarbonato de sodio y vinagre dentro de un frasco sobre una balanza. Se produce un gas (dióxido de carbono).","svg":null,"table":{"caption":"Masa medida (g)","headers":["Situación","Frasco abierto","Frasco cerrado con globo"],"rows":[["Antes de mezclar",250,252],["Después de la reacción",247.8,252]]}}'::jsonb, '¿Por qué la masa se mantiene en el frasco cerrado con globo?', '[{"label":"A","text":"Porque el globo pesa lo mismo que el gas.","is_correct":false,"distractor_type":"Inventa una compensación.","explanation_feedback":"Incorrecta. La masa se conserva porque nada escapa."},{"label":"B","text":"Porque el vinagre se evapora.","is_correct":false,"distractor_type":"Da una causa incorrecta.","explanation_feedback":"Incorrecta. Si se evaporara y escapara, la masa bajaría."},{"label":"C","text":"Porque el gas producido queda atrapado y la masa total se conserva.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Ley de conservación de la masa."},{"label":"D","text":"Porque en el frasco cerrado no hay reacción.","is_correct":false,"distractor_type":"Contradice el experimento.","explanation_feedback":"Incorrecta. La reacción ocurre en ambos."}]'::jsonb, null, 1.1, 0, 0.25, 90, 'original_generated'
