select '81872259-3d2f-555e-82a5-e6b625d0c2e3', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Bicarbonato y vinagre","text":"En un experimento se mezclan bicarbonato de sodio y vinagre dentro de un frasco sobre una balanza. Se produce un gas (dióxido de carbono).","svg":null,"table":{"caption":"Masa medida (g)","headers":["Situación","Frasco abierto","Frasco cerrado con globo"],"rows":[["Antes de mezclar",250,252],["Después de la reacción",247.8,252]]}}'::jsonb, 'Un estudiante concluye, con el frasco abierto, que en la reacción «se destruyen 2,2 g de materia». ¿Qué responde mejor?', '[{"label":"A","text":"Es correcto, porque la balanza lo muestra.","is_correct":false,"distractor_type":"No considera el gas que escapa.","explanation_feedback":"Incorrecta. El montaje cerrado muestra que la masa se conserva."},{"label":"B","text":"Es incorrecto: esos 2,2 g corresponden al gas que salió del frasco.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. El montaje cerrado muestra que la masa no se pierde."},{"label":"C","text":"Es correcto, porque el globo no influye.","is_correct":false,"distractor_type":"Ignora el papel del globo.","explanation_feedback":"Incorrecta. El globo atrapa el gas."},{"label":"D","text":"Es incorrecto, porque se crearon 2,2 g.","is_correct":false,"distractor_type":"Invierte el error.","explanation_feedback":"Incorrecta. La masa ni se crea ni se destruye."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
