select '30a03b23-86d8-5b31-84d4-f957a79772e6', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.QUI'), 'qa_passed', 'discontinuous', '{"title":"Bicarbonato y vinagre","text":"En un experimento se mezclan bicarbonato de sodio y vinagre dentro de un frasco sobre una balanza. Se produce un gas (dióxido de carbono).","svg":null,"table":{"caption":"Masa medida (g)","headers":["Situación","Frasco abierto","Frasco cerrado con globo"],"rows":[["Antes de mezclar",250,252],["Después de la reacción",247.8,252]]}}'::jsonb, 'Si se repitiera el experimento abierto con el doble de bicarbonato y suficiente vinagre, ¿qué se esperaría?', '[{"label":"A","text":"Ninguna pérdida de masa.","is_correct":false,"distractor_type":"Confunde con el montaje cerrado.","explanation_feedback":"Incorrecta. El frasco sigue abierto."},{"label":"B","text":"Una pérdida de unos 4,4 g.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. Se produce más gas, que escapa."},{"label":"C","text":"Un aumento de la masa medida.","is_correct":false,"distractor_type":"Invierte el efecto.","explanation_feedback":"Incorrecta. El gas escapa; la masa medida baja."},{"label":"D","text":"La misma pérdida, 2,2 g.","is_correct":false,"distractor_type":"Ignora la cantidad de reactivo.","explanation_feedback":"Incorrecta. Más bicarbonato produce más gas."}]'::jsonb, null, 1.3, 1.3, 0.25, 90, 'original_generated'
