select '57395a04-ec7c-5edf-b526-df20a2b14e80', e.id, 'CN', (select id from public.content_components where code = 'CN.COMP.CTS'), 'qa_passed', 'continuous', '{"title":"Paneles solares en una vereda","text":"Una vereda sin conexión a la red eléctrica instaló paneles solares en la escuela. Los paneles cargan baterías durante el día y la energía se usa en la noche para iluminar y cargar computadores. Las baterías duran unos 8 años y luego deben reemplazarse.","svg":null,"table":null}'::jsonb, '¿Qué práctica ayuda a usar de forma segura y eficiente el sistema?', '[{"label":"A","text":"Mantener limpios los paneles y no sobrecargar las baterías.","is_correct":true,"distractor_type":null,"explanation_feedback":"Correcta. La suciedad reduce la producción y la sobrecarga daña las baterías."},{"label":"B","text":"Cubrir los paneles durante el día.","is_correct":false,"distractor_type":"Impide su funcionamiento.","explanation_feedback":"Incorrecta. Los paneles necesitan luz."},{"label":"C","text":"Conectar los cables con las manos mojadas.","is_correct":false,"distractor_type":"Propone una práctica peligrosa.","explanation_feedback":"Incorrecta. El agua aumenta el riesgo de descarga."},{"label":"D","text":"Usar las baterías de noche y de día sin parar.","is_correct":false,"distractor_type":"Propone un uso ineficiente.","explanation_feedback":"Incorrecta. Agotarlas acorta su vida útil."}]'::jsonb, null, 1.1, 0, 0.25, 90, 'original_generated'
